questionvariables.text:
/* Define the constants and variables */
num: rand(5)+2; /* Coefficient of e^-x/4 */
power: 1; /* The function e^-x/4 does not depend on x^power */
upper_lm: inf; /* Upper limit of integration */
lower_lm: rand(8)+1; /* Lower limit of integration */
limit_pt: t; /* Variable for upper limit of integration */
den: rand(10)+4; /* Denominator from the exponent in e^-x/4 */
fx : num * exp(-x^power/den); /* Define the function */

/* Compute the indefinite integral */
indef_int: int(fx, x);

/* Compute the definite integral from 0 to b */
upper: at(indef_int, x = limit_pt);
lower: at(indef_int, x = lower_lm);
indef_val: upper - lower;

/* Compute the definite integral from 0 to infinity */
def_integral: limit(indef_val, limit_pt, inf);

/* Model answers */
ta_1: def_integral;
ta_2: if ta_1 = def_integral then "Convergent" elseif ta_1 = inf then "Divergent" else "Divergent";
ta_3: if ta_2 = "Convergent" then "Divergent" else "Convergent"; /* Inverse logic for clarity */
ta_4: random_permutation([[ta_2, true], [ta_3, false], ["Divergent and convergent", false]]);

feedbackvariables.text:
/*node 1:checks for correct answers*/

/*node 2:Calculating the integral as F(a)-F(b) instead of F(b)-F(a)*/
mistake_1:int(fx,upper_lm, lower_lm) ;
